final class BrowseEntry {
  final String title;
  final String subtitle;
  final BrowseRef? ref;
  final Track? track;
  BrowseEntry({
    required String title,
    required String subtitle,
    BrowseRef? ref,
    Track? track,
  }) : title = title,
       subtitle = subtitle,
       ref = ref,
       track = track {
    if ((ref == null) == (track == null)) {
      throw const FormatException(
        'BrowseEntry: exactly one of ref and track is required',
      );
    }
  }
  factory BrowseEntry.fromJson(Map<String, Object?> json) => BrowseEntry(
    title: readString(json['title'], 'BrowseEntry.title'),
    subtitle: readString(json['subtitle'], 'BrowseEntry.subtitle'),
    ref: json['ref'] == null
        ? null
        : BrowseRef.fromJson(readObject(json['ref'], 'BrowseEntry.ref')),
    track: json['track'] == null
        ? null
        : Track.fromJson(readObject(json['track'], 'BrowseEntry.track')),
  );
  Map<String, Object?> toJson() => {
    'title': title,
    'subtitle': subtitle,
    'ref': ref == null ? null : ref!.toJson(),
    'track': track == null ? null : track!.toJson(),
  };
}

